import json,struct,hashlib,base64
from pathlib import Path
p=Path("payload/app.asar")
preview=base64.b64decode("")
with p.open("rb") as f:
    prefix=f.read(8); _,hs=struct.unpack("<II",prefix); hb=f.read(hs); sl=struct.unpack("<I",hb[4:8])[0]; header=json.loads(hb[8:8+sl].decode()); base=8+hs
nodes={}
def walk(n,pre=""):
    for name,m in n.get("files",{}).items():
        q=f"{pre}/{name}" if pre else name
        if "files" in m: walk(m,q)
        else: nodes[q]=m
walk(header)
targets={"app-config.js","browser-ui.css","browser-ui.js","index.html","package-lock.json","package.json","renderer.js","mobile/www/renderer.js","document-print-preview.js","mobile/www/document-print-preview.js"}
changed={}
with p.open("rb") as f:
    for path,m in nodes.items():
        if path not in targets: continue
        f.seek(base+int(m["offset"])); original=f.read(m["size"]); data=original
        if path in {"app-config.js","browser-ui.css","browser-ui.js","index.html","package-lock.json","package.json"}:
            data=data.replace(b"1.0.28",b"1.0.29")
        if path in {"document-print-preview.js","mobile/www/document-print-preview.js"}:
            if len(preview)>m["size"]: raise RuntimeError("preview too large")
            data=preview+b" "*(m["size"]-len(preview))
        if path in {"renderer.js","mobile/www/renderer.js"}:
            s=data.decode()
            a="async function printReceipt(_0x32e176,_0x2afb75,_0x44dea7=null,_0x3b40f4='print')"
            b="async function printReceipt(_0x32e176,_0x2afb75,_0x44dea7=null,_0x3b40f4='print',L)"
            if s.count(a)!=1: raise RuntimeError(path+" signature")
            s=s.replace(a,b,1)
            a="_0x13d233=_0x34f7f5['receipt_lang'];"; b="_0x13d233=L||_0x34f7f5['receipt_lang'];"
            if s.count(a)!=1: raise RuntimeError(path+" lang")
            s=s.replace(a,b,1)
            for a,b in [
              ("_0x4bff82==='receipt2'","_0x4bff82=='receipt2'"),
              ("_0x4bff82==='receiptPremiumA5'","_0x4bff82=='receiptPremiumA5'"),
              ("_0x4bff82==='receiptPremiumThermal'","_0x4bff82=='receiptPremiumThermal'"),
              ("_0x3b40f4==='html'","_0x3b40f4=='html'"),
              ("_0x13d233!=='ar'","_0x13d233!='ar'")]:
                if a not in s: raise RuntimeError(path+" shrink "+a)
                s=s.replace(a,b,1)
            data=s.encode()
            if len(data)!=len(original): raise RuntimeError(path+" size")
        if len(data)<m["size"]: data+=b" "*(m["size"]-len(data))
        if len(data)>m["size"]: raise RuntimeError(path+" too large")
        if data==original: continue
        changed[path]=data
        integ=m.get("integrity") or {}; bs=int(integ.get("blockSize") or 4194304)
        integ["algorithm"]="SHA256"; integ["hash"]=hashlib.sha256(data).hexdigest(); integ["blockSize"]=bs
        integ["blocks"]=[hashlib.sha256(data[i:i+bs]).hexdigest() for i in range(0,len(data),bs)]
        m["integrity"]=integ
new_json=json.dumps(header,separators=(",",":"),ensure_ascii=False).encode()
if len(new_json)!=sl: raise RuntimeError("header length")
new_hb=struct.pack("<I",struct.unpack("<I",hb[:4])[0])+struct.pack("<I",sl)+new_json+hb[8+sl:]
with p.open("r+b") as f:
    f.seek(8); f.write(new_hb)
    for path,data in changed.items():
        m=nodes[path]; f.seek(base+int(m["offset"])); f.write(data)
sha=hashlib.sha256(p.read_bytes()).hexdigest()
print("app.asar sha256",sha)
if sha!="555725fdf4e2fec01617ae92402ed3c3dd55b1485f5302b6f6253d34628d009d":
    raise RuntimeError("unexpected app.asar sha "+sha)
